import {normalizeRegion} from './effect-region.js';
export function mountEffectRegion({getState,getValue,mutate,canEdit,visible,frame,bounds,finish}){
 const $=id=>document.getElementById(id),details=document.createElement('details');details.id='labRegionPanel';details.className='lab-region';
 details.innerHTML='<summary>Dónde aplicar</summary><label class="field">Efecto<select id="labRegionTarget"><option value="film">Película envejecida</option><option value="grade">Color de cine</option><option value="dustLight">Polvo de luz</option></select></label><div class="lab-region-modes"><button type="button" id="labRegionAll" aria-pressed="true">Toda la foto</button><button type="button" id="labRegionEdges" aria-pressed="false">Bordes</button></div><button type="button" id="labRegionBrush" class="button outline full" aria-pressed="false">Quitar de una zona</button><p class="lab-description">Pintá sobre la foto para quitar solo este efecto, por ejemplo del rostro. Los ajustes de Editar se conservan.</p><label class="field">Tamaño del pincel <output id="labBrushValue">12%</output><input type="range" id="labBrushSize" min="3" max="30" value="12"></label><button type="button" id="labRegionClear" class="text-button">Restaurar zonas quitadas</button><p id="labRegionStatus" class="lab-description" role="status"></p>';
 document.querySelector('.lab-component-tabs').after(details);
 const surface=document.createElement('div');surface.id='labRegionSurface';surface.hidden=true;surface.tabIndex=0;surface.setAttribute('role','application');surface.setAttribute('aria-label','Quitar efecto: pintá sobre la foto. Con teclado usá flechas para ubicar y espacio para quitar. Escape para terminar.');frame.append(surface);
 const cursor=document.createElement('span');cursor.id='labBrushCursor';surface.append(cursor);
 let painting=false,pointer=null,last=null,photo=null,keyboard={x:.5,y:.5},target='film';
 function stop(){finish();painting=false;pointer=null;last=null;surface.hidden=true;sync();}
 const value=()=>normalizeRegion(getValue()[target].region)||{mode:'all',erased:[]};
 function setMode(mode){mutate(s=>{s[target].region=normalizeRegion({...value(),mode});});}
 $('labRegionAll').onclick=()=>setMode('all');$('labRegionEdges').onclick=()=>setMode('edges');
 $('labRegionTarget').onchange=e=>{stop();target=e.target.value;sync();};
 $('labRegionBrush').onclick=()=>{painting=!painting;sync();if(painting)surface.focus({preventScroll:true});};
 $('labRegionClear').onclick=()=>mutate(s=>{s[target].region=normalizeRegion({...value(),erased:[]});});
 $('labBrushSize').oninput=()=>{last=null;syncCursor(keyboard);$('labBrushValue').textContent=$('labBrushSize').value+'%';};
 function syncCursor(point){const b=bounds(),r=surface.getBoundingClientRect(),radius=Number($('labBrushSize').value)/100*Math.min(b.width,b.height);cursor.style.width=cursor.style.height=radius*2+'px';cursor.style.left=b.left-r.left+point.x*b.width+'px';cursor.style.top=b.top-r.top+point.y*b.height+'px';}
 function stamp(point){if(!painting||!canEdit())return;const b=bounds(),radius=Number($('labBrushSize').value)/100,aspect=b.width/b.height,previous=last;const distance=previous?Math.hypot((point.x-previous.x)*Math.max(aspect,1),(point.y-previous.y)*Math.max(1/aspect,1)):0;if(previous&&distance<radius*.25)return;last=point;mutate(s=>{const region=normalizeRegion(s[target].region)||{mode:'all',erased:[]};const steps=previous?Math.min(512-region.erased.length,Math.ceil(distance/(radius*.25))):1;for(let i=1;i<=steps&&region.erased.length<512;i++){const t=i/steps;region.erased.push({x:previous?previous.x+(point.x-previous.x)*t:point.x,y:previous?previous.y+(point.y-previous.y)*t:point.y,radius});}s[target].region=region;},true);syncCursor(point);}
 function point(e){const b=bounds();if(!b.width||!b.height)return null;return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))};}
 surface.addEventListener('pointerdown',e=>{if(!painting||e.button>0||!canEdit())return;e.preventDefault();e.stopPropagation();pointer=e.pointerId;surface.setPointerCapture?.(pointer);last=null;const p=point(e);if(p)stamp(p);});
 surface.addEventListener('pointermove',e=>{const p=point(e);if(!p)return;keyboard=p;syncCursor(p);if(pointer===e.pointerId){e.preventDefault();e.stopPropagation();stamp(p);}});
 for(const name of ['pointerup','pointercancel','lostpointercapture'])surface.addEventListener(name,()=>{pointer=null;last=null;finish();});
 surface.onkeydown=e=>{if(e.key==='Escape'){stop();$('labRegionBrush').focus();return;}if(e.key===' '||e.key==='Enter'){e.preventDefault();finish();last=null;stamp(keyboard);finish();return;}const delta={ArrowLeft:[-.02,0],ArrowRight:[.02,0],ArrowUp:[0,-.02],ArrowDown:[0,.02]}[e.key];if(delta){e.preventDefault();keyboard={x:Math.max(0,Math.min(1,keyboard.x+delta[0])),y:Math.max(0,Math.min(1,keyboard.y+delta[1]))};syncCursor(keyboard);}};
 document.addEventListener('film-panel-changing',()=>stop());
 function sync(){const id=getState().activeId;if(id!==photo||!canEdit()||!visible()){painting=false;pointer=null;last=null;photo=id;}surface.hidden=!painting;frame.classList.toggle('region-painting',painting);const region=value();$('labRegionTarget').value=target;$('labRegionAll').setAttribute('aria-pressed',String(region.mode==='all'));$('labRegionEdges').setAttribute('aria-pressed',String(region.mode==='edges'));$('labRegionBrush').setAttribute('aria-pressed',String(painting));$('labRegionBrush').textContent=painting?'Terminar de quitar':'Quitar de una zona';$('labRegionClear').disabled=!canEdit()||!region.erased.length;$('labRegionStatus').textContent=region.erased.length>=512?'Llegaste al límite de trazos. Podés deshacer o restaurar las zonas.':painting?'Pintá sobre la foto · deshacer revierte el último trazo.':region.erased.length?'Este efecto tiene zonas quitadas.':'';if(painting)syncCursor(keyboard);return painting;}
 function select(key){painting=false;pointer=null;last=null;target=key;sync();}
 return {sync,select,isPainting:()=>painting};
}
